function stuckLandCells(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const escapes = (si: number, sj: number): boolean => {
    const seen = new Set<number>([si * n + sj]);
    const q: number[][] = [[si, sj]];
    for (let h = 0; h < q.length; h++) {
      const [i, j] = q[h];
      if (i === 0 || j === 0 || i === m - 1 || j === n - 1) return true;
      for (const [a, b] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]]) {
        if (grid[a][b] === 1 && !seen.has(a * n + b)) { seen.add(a * n + b); q.push([a, b]); }
      }
    }
    return false;
  };
  let count = 0;
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++)
      if (grid[i][j] === 1 && !escapes(i, j)) count++;
  return count;
}

