function stuckLandCells(grid: number[][]): number {
  const m = grid.length, n = grid[0].length;
  const g = grid.map(row => row.slice());
  const stack: number[] = [];
  const push = (i: number, j: number) => {
    if (i >= 0 && j >= 0 && i < m && j < n && g[i][j] === 1) { g[i][j] = 0; stack.push(i * n + j); }
  };
  for (let i = 0; i < m; i++) { push(i, 0); push(i, n - 1); }
  for (let j = 0; j < n; j++) { push(0, j); push(m - 1, j); }
  while (stack.length) {
    const v = stack.pop()!, i = Math.floor(v / n), j = v % n;
    push(i + 1, j); push(i - 1, j); push(i, j + 1); push(i, j - 1);
  }
  let count = 0;
  for (const row of g) for (const x of row) count += x;
  return count;
}

